import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    genres = list(map(int, data[2:2+n]))

    # Count books in each genre
    count = [0] * (m + 1)
    for genre in genres:
        count[genre] += 1

    # Calculate total ways
    total = 0
    for i in range(1, m + 1):
        for j in range(i + 1, m + 1):
            total += count[i] * count[j]

    print(total)

if __name__ == "__main__":
    solve()
