def hamming_distance(x, y):
    return bin(x ^ y).count('1')

n, k = map(int, input().split())
a = list(map(int, input().split()))

from collections import Counter

freq = Counter(a)

if k == 0:
    # Count pairs of equal numbers
    result = 0
    for count in freq.values():
        result += count * (count - 1) // 2
else:
    # Count pairs with Hamming distance exactly k
    result = 0
    values = list(freq.keys())
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if hamming_distance(values[i], values[j]) == k:
                # Count how many times this pair appears
                result += freq[values[i]] * freq[values[j]]

print(result)
"}

