import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    unique_or = set()

    for l in range(n):
        current_or = 0
        for r in range(l, n):
            current_or |= a[r]
            if current_or == previous_or:
                break
            unique_or.add(current_or)
            previous_or = current_or

    print(len(unique_or))

if __name__ == "__main__":
    solve()
"}

