def find_beautiful_sequence(q, k):
    """Find a beautiful sequence of k strings that concatenate to q."""
    n = len(q)

    # Try all possible ways to split the string into k parts
    for first_split in range(1, n):
        s1 = q[:first_split]
        remaining = q[first_split:]

        # Try all possible ways to split the remaining string into k-1 parts
        for second_split in range(1, len(remaining)):
            s2 = remaining[:second_split]
            remaining2 = remaining[second_split:]

            # Check if first characters are distinct
            if len(set([s1[0], s2[0]])) == 2:
                # Check if we can split the remaining into k-2 parts
                if k == 2:
                    if len(remaining2) > 0:
                        return [s1, s2]
                else:
                    # Try all possible ways to split the remaining into k-2 parts
                    for third_split in range(1, len(remaining2)):
                        s3 = remaining2[:third_split]
                        remaining3 = remaining2[third_split:]

                        # Check if first characters are distinct
                        if len(set([s1[0], s2[0], s3[0]])) == 3:
                            if k == 3:
                                if len(remaining3) > 0:
                                    return [s1, s2, s3]
                            else:
                                # This approach gets too complicated for k > 3
                                # Let me think of a better way
                                pass

    # If we couldn't find a solution
    return None

