    # Try all possible ways to split the string into k parts
    # We need to make k-1 splits
    # We'll try all possible positions for the splits

    # This is a recursive approach to try all possible splits
    def try_split(start, parts):
        """Try to split from position `start` into `parts` parts."""
        if parts == 1:
            # Last part, just take the rest
            return [q[start:]]

        # Try all possible end positions for this part
        for end in range(start + 1, n + 1):
            # This part is q[start:end]
            # First character must be distinct from previous parts
            if not parts or q[end - 1] not in [part[0] for part in parts]:
                # Try to split the remaining into parts - 1 parts
                remaining = try_split(end, parts - 1)
                if remaining:
                    return [q[start:end]] + remaining

        return None

    solution = try_split(0, k)

    if solution:
        print("YES")
        for s in solution:
            print(s)
    else:
        print("NO")
