def can_form_palindrome(s):
    """Check if the string can be rearranged into a palindrome"""
    odd_counts = 0
    freq = {}

    for char in s:
        freq[char] = freq.get(char, 0) + 1

    for count in freq.values():
        if count % 2 != 0:
            odd_counts += 1

    return odd_counts <= 1

def solve(s):
    """Determine if the first player or second player wins"""
    odd_counts = 0
    freq = {}

    for char in s:
        freq[char] = freq.get(char, 0) + 1

    for count in freq.values():
        if count % 2 != 0:
            odd_counts += 1

    # If there are 0 or 1 odd-count characters, first player wins
    if odd_counts <= 1:
        return "First"

    # If there are an even number of odd-count characters (> 1), second player wins
    if odd_counts % 2 == 0 and odd_counts > 1:
        return "Second"

    # If there are an odd number of odd-count characters (> 1), first player wins
    if odd_counts % 2 == 1 and odd_counts > 1:
        return "First"

# Read input and output result
s = input().strip()
print(solve(s))
"}

