n, m, c0, d0 = map(int, input().split())

# Read stuffing information
stuffings = []
for _ in range(m):
    a, b, c, d = map(int, input().split())
    max_buns = a // b  # Maximum buns we can make with this stuffing
    stuffings.append((max_buns, c, d))

# DP array: dp[j] = maximum tugriks we can earn with j grams of dough
dp = [0] * (n + 1)

# Consider "no stuffing" buns (unbounded knapsack)
for j in range(c0, n + 1):
    dp[j] = max(dp[j], dp[j - c0] + d0)

# Consider each stuffing type (bounded knapsack)
for max_buns, c, d in stuffings:
    # We can make 0 to max_buns of this type
    for j in range(n, c - 1, -1):
        # Try all possible counts of this type
        for k in range(1, max_buns + 1):
            if j - k * c >= 0:
                dp[j] = max(dp[j], dp[j - k * c] + k * d)

print(dp[n])
"}

