def topological_sort(n, edges):
    # Build adjacency list and indegree array
    adj = [[] for _ in range(n + 1)]
    indegree = [0] * (n + 1)

    for u, v in edges:
        adj[u].append(v)
        indegree[v] += 1

    # Queue for nodes with indegree 0
    queue = [i for i in range(1, n + 1) if indegree[i] == 0]
    result = []

    while queue:
        u = queue.pop(0)
        result.append(u)

        for v in adj[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)

    # If we didn't visit all nodes, there's a cycle
    if len(result) != n:
        return -1

    return result

def main():
    import sys
    input = sys.stdin.read().strip().split()

    if not input:
        return

    data = iter(input)
    n = int(next(data))
    m = int(next(data))

    edges = []
    for _ in range(m):
        u = int(next(data))
        v = int(next(data))
        edges.append((u, v))

    order = topological_sort(n, edges)

    if order == -1:
        print(-1)
    else:
        print(' '.join(map(str, order)))

if __name__ == "__main__":
    main()
