import sys
from collections import deque, defaultdict

def bfs(adj, visited, match_to, u, n_right):
    """BFS to find augmenting path"""
    queue = deque([u])
    visited[u] = True

    while queue:
        curr = queue.popleft()
        for neighbor in adj[curr]:
            if not visited[neighbor]:
                visited[neighbor] = True

                # If neighbor is not matched or can be rematched
                if match_to.get(neighbor, -1) == -1 or bfs(adj, visited, match_to, match_to.get(neighbor, -1), n_right):
                    match_to[neighbor] = curr
                    return True

                # If neighbor is matched, add to queue for further exploration
                if match_to.get(neighbor, -1) != -1:
                    queue.append(match_to.get(neighbor, -1))

            # If neighbor is not matched and we can't extend, backtrack
            elif match_to.get(neighbor, -1) == -1:
                visited[neighbor] = False

    return False

def hopcroft_karp(adj, n_left, n_right):
    """Find maximum bipartite matching"""
    match_to = {}  # Matched to which left node

    # Build adjacency list for left nodes
    left_adj = defaultdict(list)
    for left, right in adj.items():
        left_adj[left].extend(right)

    result = 0

    while bfs(left_adj, [False] * (n_left + 1), match_to, 1, n_right):
        result += 1

    return result

def solve():
