    if not data:
        return

    it = iter(data)
    N = int(next(it))
    M = int(next(it))

    # Build adjacency list for left nodes (airports)
    adj = defaultdict(list)

    for _ in range(M):
        u = int(next(it))
        v = int(next(it))
        d = int(next(it))
        adj[u].append((v, d))

    # Binary search on the answer
    left = 1
    right = 10**9
    answer = -1

    while left <= right:
        mid = (left + right) // 2

        # Build adjacency list with edges ≤ mid
        temp_adj = defaultdict(list)
        for u, edges in adj.items():
            for v, d in edges:
                if d <= mid:
                    temp_adj[u].append((v, d))

        # Check if perfect matching exists
        if hopcroft_karp(temp_adj, N, N) == N:
            answer = mid
            right = mid - 1
        else:
            left = mid + 1

    print(answer)

