def compute_grundy(n):
    """Compute Grundy numbers for piles up to n"""
    g = [0] * (n + 1)

    for m in range(2, n + 1):
        reachable = set()

        # Try all possible splits
        for k in range(2, m + 1):
            # Check if split into k piles is valid
            # Sizes: a, a-1, ..., a-(k-1)
            # Sum = k*a - k*(k-1)/2 = m
            # k*a = m + k*(k-1)/2
            # a = (m/k) + (k-1)/2

            # For a to be integer:
            # - If k odd, m/k must be integer
            # - If k even, (k-1)/2 is not integer, so m/k must be half-integer (i.e., m odd)

            if k % 2 == 1:
                if m % k == 0:
                    a = (m // k) + (k - 1) // 2
                    sizes = [a - i for i in range(k)]
                    # Check if all sizes > 0
                    if all(s > 0 for s in sizes):
                        # Compute Grundy of this state
                        state_grundy = 0
                        for s in sizes:
                            state_grundy ^= g[s]
                        reachable.add(state_grundy)
            else:
                if m % 2 == 1:
                    a = (m // k) + (k - 1) // 2
                    sizes = [a - i for i in range(k)]
                    # Check if all sizes > 0
                    if all(s > 0 for s in sizes):
                        # Compute Grundy of this state
                        state_grundy = 0
                        for s in sizes:
                            state_grundy ^= g[s]
                        reachable.add(state_grundy)

        g[m] = min(excluded for excluded in range(len(reachable)) if excluded not in reachable)

    return g

