def solve():
    n = input().strip()

    # Convert to list of integers
    digits = [int(c) for c in n]

    # Calculate sum of digits
    total_sum = sum(digits)

    # If sum is already a multiple of 3
    if total_sum % 3 == 0:
        # If there are no leading zeroes, just output
        if n[0] != '0':
            print(n)
        else:
            # Find first non-zero digit
            first_non_zero = next(i for i, d in enumerate(digits) if d != 0)
            print(n[first_non_zero:])
