def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))
    h = [int(next(it)) for _ in range(n)]

    results = []

    for _ in range(q):
        l = int(next(it)) - 1  # convert to 0-indexed
        r = int(next(it)) - 1

        total = 0

        # Consider all subarrays of h[l..r]
        for start in range(l, r + 1):
            for end in range(start, r + 1):
                # subarray from start to end inclusive
                sub_len = end - start + 1
                if sub_len == 1:
                    continue  # Lipschitz constant is 0

                # Find maximum |h[i] - h[j]| / (j-i) for i < j in this subarray
                max_L = 0
                for i in range(start, end):
                    for j in range(i + 1, end + 1):
                        diff = abs(h[i] - h[j])
                        dist = j - i
                        L = diff / dist
                        if L > max_L:
                            max_L = L

                total += max_L

        results.append(total)

    for result in results:
        print(int(result))

