def can_place(weights, m, available_weights):
    """Check if we can place m weights following the rules"""
    # Backtracking to try different sequences
    def backtrack(index, left_total, right_total, last_weight):
        # index: current weight position (1-indexed)
        # left_total: total weight on left pan
        # right_total: total weight on right pan
        # last_weight: weight of the previously placed weight (or None for first)

        if index > m:
            return True, []  # Found a valid sequence

        # Determine which pan to place the next weight
        if index % 2 == 1:
            # Odd index: place on left
            for weight in range(1, 11):
                if available_weights[weight - 1] and weight != last_weight:
                    # Check if left pan outweighs right pan after placing this weight
                    if left_total + weight > right_total:
                        # Recursively try to place remaining weights
                        success, sequence = backtrack(index + 1, left_total + weight, right_total, weight)
                        if success:
                            return True, [weight] + sequence
            return False, []
        else:
            # Even index: place on right
            for weight in range(1, 11):
                if available_weights[weight - 1] and weight != last_weight:
                    # Check if right pan outweighs left pan after placing this weight
                    if right_total + weight > left_total:
                        # Recursively try to place remaining weights
                        success, sequence = backtrack(index + 1, left_total, right_total + weight, weight)
                        if success:
                            return True, [weight] + sequence
            return False, []

    success, sequence = backtrack(1, 0, 0, None)
    return success, sequence

def solve():
    available_weights = input().strip()
    m = int(input())

    # Convert string to list of booleans
    available_weights = [char == '1' for char in available_weights]

    success, sequence = can_place(available_weights, m)

    if success:
        print("YES")
        print(" ".join(map(str, sequence)))
    else:
        print("NO")

