def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    b = list(map(int, data[1:2*n+1]))

    # Generate primes up to the maximum value in b using Sieve of Eratosthenes
    max_b = max(b)
    is_prime = [True] * (max_b + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(math.sqrt(max_b)) + 1):
        if is_prime[i]:
            for j in range(i * i, max_b + 1, i):
                is_prime[j] = False

    # Map from prime to its position (1-indexed)
    prime_position = {}
    for i in range(2, max_b + 1):
        if is_prime[i]:
            prime_position[i] = i  # position of prime i is i

    # Map from number to its smallest prime factor
    smallest_prime_factor = [0] * (max_b + 1)
    for i in range(2, max_b + 1):
        if is_prime[i]:
            smallest_prime_factor[i] = i
        for j in range(i * i, max_b + 1, i):
            if smallest_prime_factor[j] == 0:
                smallest_prime_factor[j] = i

    # Function to get largest proper divisor
    def largest_proper_divisor(x):
        if x % 2 == 0:
            return x // 2
        for i in range(3, int(math.sqrt(x)) + 1, 2):
            if x % i == 0:
                return x // i
        return 1  # shouldn't happen for x >= 2

    # Try to find pairs
    used = [False] * len(b)
    result = []

    for i in range(len(b)):
        if used[i]:
            continue

        x = b[i]

        # Try to find match for x
        found = False

        if is_prime[x]:
            # x could be a prime in a, and we need to find p[x] in b
            target = prime_position.get(x, -1)
            if target != -1 and not used[target]:
                # x is the prime in a, and target is p[x]
                result.append(x)
                used[i] = used[target] = True
                found = True
        else:
            # x could be a non-prime in a, and we need to find its largest proper divisor
            target = largest_proper_divisor(x)
            if target in b and not used[b.index(target)]:
                # x is the non-prime in a, and target is its largest proper divisor
                result.append(x)
                used[i] = used[b.index(target)] = True
                found = True

        if not found:
            # Try to find x as the largest proper divisor of some other element
            # We need to find an element y such that largest_proper_divisor(y) = x
            # This means y = x * p, where p is the smallest prime factor of y
            # So y = x * smallest_prime_factor[y]
            # We need to check if x * smallest_prime_factor[y] exists in b

            # We'll check all primes p
            for p in range(2, int(math.sqrt(x)) + 1):
                if is_prime[p]:
                    y = x * p
                    if y in b and not used[b.index(y)]:
                        # x is the largest proper divisor of y
                        result.append(y)
                        used[i] = used[b.index(y)] = True
                        found = True
                        break

            if not found:
                # Try the other case: x is the smallest prime factor of y
                # Then y = x * k, and largest_proper_divisor(y) = k
                # So we need to find k such that k is in b and k = y / x
                # And we need to check if x * k exists in b
                for k in b:
                    if k == x:
                        continue
                    if k in b and not used[b.index(k)]:
                        y = x * k
                        if y in b and not used[b.index(y)]:
                            # x is the smallest prime factor of y
                            result.append(y)
                            used[i] = used[b.index(k)] = used[b.index(y)] = True
                            found = True
                            break

        if found:
            continue

        # If we still haven't found, try to find x as an element of a
        # and its corresponding appended element
        for y in b:
            if y == x:
                continue
            if used[y]:
                continue

            if is_prime[x]:
                # x is prime, y should be p[x]
                if y == prime_position.get(x, -1):
                    result.append(x)
                    used[i] = used[y] = True
                    found = True
                    break
            else:
