                # x is the prime in a, and target is p[x]
                result.append(x)
                used[i] = used[target] = True
                found = True
        else:
            # x could be a non-prime in a, and we need to find its largest proper divisor
            target = largest_proper_divisor(x)
            if target in b and not used[b.index(target)]:
                # x is the non-prime in a, and target is its largest proper divisor
                result.append(x)
                used[i] = used[b.index(target)] = True
                found = True

        if not found:
            # Try to find x as the largest proper divisor of some other element
            # We need to find an element y such that largest_proper_divisor(y) = x
            # This means y = x * p, where p is the smallest prime factor of y
            # So y = x * smallest_prime_factor[y]
            # We need to check if x * smallest_prime_factor[y] exists in b

            # We'll check all primes p
            for p in range(2, int(math.sqrt(x)) + 1):
                if is_prime[p]:
                    y = x * p
                    if y in b and not used[b.index(y)]:
                        # x is the largest proper divisor of y
                        result.append(y)
                        used[i] = used[b.index(y)] = True
                        found = True
                        break

            if not found:
                # Try the other case: x is the smallest prime factor of y
                # Then y = x * k, and largest_proper_divisor(y) = k
                # So we need to find k such that k is in b and k = y / x
                # And we need to check if x * k exists in b
                for k in b:
