import sys
import math

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    b = list(map(int, data[1:2*n+1]))

    # Generate primes up to the maximum value in b using Sieve of Eratosthenes
    max_b = max(b)
    is_prime = [True] * (max_b + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(math.sqrt(max_b)) + 1):
        if is_prime[i]:
            for j in range(i * i, max_b + 1, i):
                is_prime[j] = False

    # Map from prime to its position (1-indexed)
    prime_position = {}
    for i in range(2, max_b + 1):
        if is_prime[i]:
            prime_position[i] = i  # position of prime i is i

    # Map from number to its smallest prime factor
    smallest_prime_factor = [0] * (max_b + 1)
    for i in range(2, max_b + 1):
        if is_prime[i]:
            smallest_prime_factor[i] = i
        for j in range(i * i, max_b + 1, i):
            if smallest_prime_factor[j] == 0:
                smallest_prime_factor[j] = i

    # Function to get largest proper divisor
    def largest_proper_divisor(x):
        if x % 2 == 0:
            return x // 2
        for i in range(3, int(math.sqrt(x)) + 1, 2):
            if x % i == 0:
                return x // i
        return 1  # shouldn't happen for x >= 2

    # Function to get smallest proper divisor
    def smallest_proper_divisor(x):
        if x % 2 == 0:
            return 2
        for i in range(3, int(math.sqrt(x)) + 1, 2):
            if x % i == 0:
                return i
        return x  # shouldn't happen for x >= 2

    # Count frequencies
    freq = {}
    for num in b:
        freq[num] = freq.get(num, 0) + 1

    # Try to find a by working backwards
    a = []
    used = [False] * len(b)

    for i in range(len(b)):
        if used[i]:
            continue

        x = b[i]

        # Check if x could be from a
        if freq[x] == 1:
            # If x appears only once, it must be from a
            # We need to find its appended element
            if is_prime[x]:
                # x is prime, appended element is p_x
                appended = prime_position.get(x, -1)
            else:
                # x is non-prime, appended element is its largest proper divisor
                appended = largest_proper_divisor(x)

            # Find appended in b
            appended_idx = -1
            for j in range(len(b)):
                if not used[j] and b[j] == appended:
                    appended_idx = j
                    break

            if appended_idx != -1:
                # Match x with appended
                a.append(x)
                used[i] = used[appended_idx] = True


    # Print result
    print(' '.join(map(str, a)))

solve()

