import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    for _ in range(t):
        n = int(data[idx])
        p = int(data[idx + 1])
        idx += 2

        # We need a graph with exactly 2n + p edges
        # And for any subset of k vertices, at most 2k + p edges

        # Start with vertex 1 connected to all other vertices
        edges = []
        for i in range(2, n + 1):
            edges.append((1, i))

        # Calculate how many more edges we need
        needed = 2 * n + p - len(edges)

        # Add edges between vertex 2 and vertices 3 to n
        for i in range(3, n + 1):
            if needed <= 0:
                break
            edges.append((2, i))
            needed -= 1

        # Add edges between vertex 3 and vertices 4 to n
        for i in range(4, n + 1):
            if needed <= 0:
                break
            edges.append((3, i))
            needed -= 1

        # Add edges between other vertices
        for i in range(4, n):
            for j in range(i + 1, n + 1):
                if needed <= 0:
                    break
                edges.append((i, j))
                needed -= 1

        # Print the result
        for a, b in edges:
            print(a, b)

if __name__ == "__main__":
    solve()
