import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    k1 = int(next(it))
    k2 = int(next(it))
    k3 = int(next(it))

    # Read first participant's problems
    a1 = [int(next(it)) for _ in range(k1)]
    # Read second participant's problems
    a2 = [int(next(it)) for _ in range(k2)]
    # Read third participant's problems
    a3 = [int(next(it)) for _ in range(k3)]

    # Combine all problems
    all_problems = set(a1 + a2 + a3)
    n = len(all_problems)

    # Count problems each participant has
    count_first = {}
    count_second = {}
    count_third = {}

    for p in a1:
        count_first[p] = count_first.get(p, 0) + 1
    for p in a2:
        count_second[p] = count_second.get(p, 0) + 1
    for p in a3:
        count_third[p] = count_third.get(p, 0) + 1

    # Try all possible splits
    min_moves = float('inf')

    # First gets [1, x], Third gets [y, n], Second gets [x+1, y-1]
    # We need to try all possible x and y

    # x can range from 0 to n
    # y can range from x+1 to n

    for x in range(n + 1):
        for y in range(x + 1, n + 1):
            # Count problems that should go to first
            first_should = set(range(1, x + 1))
            # Count problems that should go to third
            third_should = set(range(y, n + 1))
            # Count problems that should go to second
            second_should = set(range(x + 1, y))

            # Count problems that should go to first but are not with first
            moves = 0
            for p in first_should:
                if p not in count_first or count_first[p] == 0:
                    moves += 1
            for p in third_should:
                if p not in count_third or count_third[p] == 0:
                    moves += 1
            for p in second_should:
                if p not in count_second or count_second[p] == 0:
                    moves += 1

            min_moves = min(min_moves, moves)

    print(min_moves)

if __name__ == "__main__":
    solve()
