import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    grid = data[2:2+n]

    # Find the minimum valid frame size
    min_size = float('inf')
    best_i, best_j, best_d = -1, -1, -1

    # Try all possible top-left corners
    for i in range(n):
        for j in range(m):
            # Try all possible side lengths starting from 1
            for d in range(1, min(n - i, m - j) + 1):
                # Check if all white pixels are on the border
                valid = True

                # Check non-border area
                for x in range(i + 1, i + d - 1):
                    for y in range(j + 1, j + d - 1):
                        if grid[x][y] == 'w':
                            valid = False
                            break
                    if not valid:
                        break

                if valid:
                    # Check if there are any white pixels not on the border
                    # (we already checked non-border, but need to ensure border has whites)
                    # Actually, we just need to ensure no whites in non-border
                    # And we need at least one white pixel on the border
                    has_white_on_border = False

                    # Check border pixels
                    for x in range(i, i + d):
                        for y in range(j, j + d):
                            if x == i or x == i + d - 1 or y == j or y == j + d - 1:
                                if grid[x][y] == 'w':
                                    has_white_on_border = True
                                    break
                        if has_white_on_border:
                            break

                    if has_white_on_border:
                        # This is a valid frame
                        if d < min_size:
                            min_size = d
                            best_i, best_j, best_d = i, j, d

    if min_size == float('inf'):
        print(-1)
    else:
        # Draw the result
        result = [list(row) for row in grid]
        for x in range(best_i, best_i + best_d):
            for y in range(best_j, best_j + best_d):
                if x == best_i or x == best_i + best_d - 1 or y == best_j or y == best_j + best_d - 1:
                    result[x][y] = '+'

        for row in result:
            print(''.join(row))

if __name__ == "__main__":
    solve()
