import sys

def lipschitz_constant(subarray):
    """Compute the Lipschitz constant for a subarray."""
    n = len(subarray)
    if n < 2:
        return 0

    max_slope = 0
    for i in range(n):
        for j in range(i + 1, n):
            slope = abs(subarray[i] - subarray[j]) / (j - i)
            if slope > max_slope:
                max_slope = slope

    return int(max_slope) + 1  # Ceiling function

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))

    h = [int(next(it)) for _ in range(n)]

    for _ in range(q):
        l = int(next(it)) - 1  # Convert to 0-indexed
        r = int(next(it)) - 1

        # Consider subarray h[l..r]
        subarray = h[l:r+1]
        total = 0

        # For each sub-subarray of h[l..r]
        m = len(subarray)
        for start in range(m):
            for end in range(start + 1, m + 1):
                # Sub-subarray from start to end (inclusive)
                subsubarray = subarray[start:end]
                total += lipschitz_constant(subsubarray)

        print(total)

if __name__ == "__main__":
    solve()
"}

