import sys

def solve():
    # Read input
    available = sys.stdin.readline().strip()
    m = int(sys.stdin.readline())

    # Parse available weights
    available_weights = []
    for i in range(10):
        if available[i] == '1':
            available_weights.append(i + 1)

    # Try to find a valid sequence using backtracking
    def backtrack(prev_weight, left_sum, right_sum, depth, path):
        if depth == m:
            return path.copy()

        # Determine which scalepan we're placing on
        if depth % 2 == 0:
            # Even depth (0-indexed), place on left
            # After placing, left should be > right
            for weight in available_weights:
                if weight != prev_weight:
                    new_left = left_sum + weight
                    if new_left > right_sum:
                        path.append(weight)
                        result = backtrack(weight, new_left, right_sum, depth + 1, path)
                        if result is not None:
                            return result
                        path.pop()
        else:
            # Odd depth, place on right
            # After placing, right should be > left
            for weight in available_weights:
                if weight != prev_weight:
                    new_right = right_sum + weight
                    if new_right > left_sum:
                        path.append(weight)
                        result = backtrack(weight, left_sum, new_right, depth + 1, path)
                        if result is not None:
