import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    I = int(data[1])
    arr = list(map(int, data[2:2+n]))

    # Count frequencies
    freq = {}
    for val in arr:
        freq[val] = freq.get(val, 0) + 1

    # Sort frequencies in descending order
    freq_list = sorted(freq.values(), reverse=True)

    # Calculate maximum K we can keep
    max_k = 0
    for k in range(1, len(freq_list) + 1):
        bits_needed = n * ((k + 1) // 1)  # k = ceil(log2(k))
        if bits_needed <= 8 * I:
            max_k = k
        else:
            break

    # Sum the top max_k frequencies
    unchanged = sum(freq_list[:max_k])
    changed = n - unchanged

    print(changed)

if __name__ == "__main__":
    solve()
