import sys

def lipschitz_constant(subarray):
    """Compute the Lipschitz constant for a subarray."""
    n = len(subarray)
    if n < 2:
        return 0

    max_slope = 0
    for i in range(n):
        for j in range(i + 1, n):
            slope = abs(subarray[i] - subarray[j]) / (j - i)
            max_slope = max(max_slope, slope)

    return int(max_slope)

def solve():
