import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    coords = [int(next(it)) for _ in range(n + m)]
    types = [int(next(it)) for _ in range(n + m)]

    # Separate into riders and taxi drivers
    riders = []
    taxi_drivers = []

    for coord, typ in zip(coords, types):
        if typ == 0:
            riders.append(coord)
        else:
            taxi_drivers.append(coord)

    # For each rider, find the closest taxi driver
    result = [0] * m

    for rider in riders:
        # Find the closest taxi driver
        closest_idx = -1
        min_dist = float('inf')

        for i, taxi in enumerate(taxi_drivers):
            dist = abs(rider - taxi)
            if dist < min_dist:
                min_dist = dist
                closest_idx = i
            elif dist == min_dist:
                # Tie: choose the taxi driver with smaller coordinate
                if taxi < taxi_drivers[closest_idx]:
                    closest_idx = i

        result[closest_idx] += 1

    print(' '.join(map(str, result)))

if __name__ == '__main__':
    solve()
"}

