    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    genres = list(map(int, data[2:2+n]))

    # Count occurrences of each genre
    count = {}
    for genre in genres:
        count[genre] = count.get(genre, 0) + 1

    # Calculate total ways
    total = 0
    genres_list = list(count.keys())
    for i in range(len(genres_list)):
        for j in range(i + 1, len(genres_list)):
            total += count[genres_list[i]] * count[genres_list[j]]

    print(total)

if __name__ == "__main__":
    solve()

