import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    total_sum = sum(a)

    result = []
    for j in range(n):
        # Check if there exists an element a[i] (i != j) such that a[j] = total_sum - 2 * a[i]
        # This means we need to find if there is an element equal to (total_sum - a[j]) / 2
        target = (total_sum - a[j]) / 2

        # Check if target is an integer and exists in the array (excluding the current element)
        if target.is_integer():
            target = int(target)
            # Check if target exists in the array and is not the same element (or if it is, check if there are multiple occurrences)
            if a.count(target) > 0:
                # If target is the same as a[j], we need at least two occurrences
                if target == a[j] and a.count(target) >= 2:
                    result.append(j + 1)  # 1-indexed
                # If target is different, we just need at least one occurrence
                elif target != a[j]:
                    result.append(j + 1)

    print(len(result))
    if result:
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()
