import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    # Build reversed graph (borrower -> lender)
    graph = [[] for _ in range(n + 1)]
    in_degree = [0] * (n + 1)

    idx = 2
    for _ in range(m):
        a = int(data[idx])
        b = int(data[idx + 1])
        idx += 2

        # Edge from borrower a to lender b
        graph[a].append(b)
        in_degree[b] += 1

    # Topological sort using Kahn's algorithm
    queue = []
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    while queue:
        u = queue.pop(0)
        result.append(u)

        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(result) != n:
        print(-1)
    else:
        print(' '.join(map(str, result)))

if __name__ == "__main__":
