import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    # Build graph (borrower -> lender)
    graph = [[] for _ in range(n + 1)]

    idx = 2
    for _ in range(m):
        a = int(data[idx])
        b = int(data[idx + 1])
        idx += 2

        graph[a].append(b)

    # Try to find an ordering where we don't have consecutive elements with an edge from first to second
    # This is like finding a topological sort that avoids consecutive edges

    # We can use a greedy approach: always pick a node with no incoming edges
    in_degree = [0] * (n + 1)
    for a in range(1, n + 1):
        for b in graph[a]:
            in_degree[b] += 1

    queue = []
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    while queue:
        u = queue.pop(0)
        result.append(u)

        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(result) != n:
        print(-1)
    else:
        # Check if the result satisfies the condition
        valid = True
        for i in range(n - 1):
            a = result[i]
            b = result[i + 1]
            if b in graph[a]:
                valid = False
                break

        if valid:
