import sys

def can_achieve(n, r, k, a, target):
    """Check if we can achieve at least `target` defense level everywhere"""
    # Calculate initial defense levels
    defense = [0] * n
    for i in range(n):
        for j in range(max(0, i - r), min(n, i + r + 1)):
            defense[j] += a[i]

    # Greedy approach to add archers
    archers_added = 0
    for i in range(n):
        if defense[i] < target:
            # Need to add archers to cover section i
            # Add them to the farthest possible position that can cover i
            pos = min(i + r, n - 1)

            needed = target - defense[i]
            if needed <= 0:
                continue

            # Add needed archers to position pos
            archers_added += needed
            if archers_added > k:
                return False

            # Update defense levels for the range affected by pos
            for j in range(max(0, pos - r), min(n, pos + r + 1)):
                defense[j] += needed

    return True

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    r = int(data[1])
    k = int(data[2])
    a = list(map(int, data[3:3+n]))

    # Binary search on the answer
    low = 0
    high = 0
    for ai in a:
        high = max(high, ai)

    answer = 0
    while low <= high:
        mid = (low + high) // 2
        if can_achieve(n, r, k, a, mid):
            answer = mid
            low = mid + 1
        else:
            high = mid - 1

    print(answer)

if __name__ == "__main__":
    solve()
"}

