import sys

def matches(word, pattern):
    """Check if word matches pattern"""
    # Count the number of '?' in the pattern
    k = pattern.count('?')

    # Try all combinations of which '?' to remove (up to 3 choices)
    for remove_indices in range(1 << k):
        # Create a new pattern by removing some '?'
        new_pattern = []
        for i, ch in enumerate(pattern):
            if ch == '?' and (remove_indices & (1 << (i - pattern.count('?', 0, i)))):
                continue  # Skip this '?"
            new_pattern.append(ch)

        # Check if the resulting pattern matches the word
        if len(new_pattern) > len(word):
            continue

        match = True
        for w_char, p_char in zip(word, new_pattern):
            if p_char != '?' and p_char != w_char:
                match = False
                break

        if match:
            return True

    return False

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    words = []
    for _ in range(n):
        words.append(next(it))

    results = []
    for _ in range(m):
        pattern = next(it)
        count = 0
        for word in words:
            if matches(word, pattern):
                count += 1
        results.append(str(count))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
