import sys

def solve():
    # Read input
    weights_str = sys.stdin.readline().strip()
    m = int(sys.stdin.readline())

    # Parse available weights
    available_weights = []
    for i in range(10):
        if weights_str[i] == '1':
            available_weights.append(i + 1)

    # If no weights are available, it's impossible
    if not available_weights:
        print("NO")
        return

    # Try to build the sequence
    sequence = []
    left_sum = 0
    right_sum = 0

    # Backtracking approach
    def backtrack(position):
        # If we've placed all m weights, we're done
        if position == m:
            return True

        # Determine which scalepan we're placing on
        if position % 2 == 0:
            # Left scalepan
            current_scale = 'left'
            current_sum = left_sum
            other_sum = right_sum
        else:
            # Right scalepan
            current_scale = 'right'
            current_sum = right_sum
            other_sum = left_sum

        # Try each available weight
        for weight in sorted(available_weights):
            # Skip if we can't place this weight (either sum is not greater or consecutive same weights)
            if position > 0 and weight == sequence[-1]:
                continue  # Skip consecutive same weights

            # Check if placing this weight makes the current scalepan outweigh
            if current_scale == 'left':
                if current_sum + weight > other_sum:
                    # Place the weight
                    sequence.append(weight)
                    if position % 2 == 0:
                        left_sum += weight
                    else:
                        right_sum += weight

                    # Recursively try to place the next weight
                    if backtrack(position + 1):
                        return True

                    # Backtrack
                    sequence.pop()
                    if position % 2 == 0:
                        left_sum -= weight
                    else:
                        right_sum -= weight
            else:
                if current_sum + weight > other_sum:
                    sequence.append(weight)
                    if position % 2 == 0:
                        left_sum += weight
                    else:
                        right_sum += weight

                    if backtrack(position + 1):
                        return True

                    sequence.pop()
                    if position % 2 == 0:
                        left_sum -= weight
                    else:
                        right_sum -= weight

        return False

    if backtrack(0):
        print("YES")
        print(' '.join(map(str, sequence)))
    else:
        print("NO")

if __name__ == "__main__":
    solve()
