                valid = True
                # Check all white pixels
                for i in range(n):
                    for j in range(m):
                        if grid[i][j] == 'w':
                            # Check if (i, j) is on the frame
                            if not ((i == x and y <= j <= y + d - 1) or
                                    (i == x + d - 1 and y <= j <= y + d - 1) or
                                    (j == y and x < i < x + d - 1) or
                                    (j == y + d - 1 and x < i < x + d - 1)):
