import sys

def solve():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return

    idx = 0
    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        # Skip empty lines
        while idx < len(data) and data[idx] == '':
            idx += 1
        if idx >= len(data):
            break

        n = int(data[idx])
        idx += 1

        # Read matrix a
        a = []
        for _ in range(n):
            while idx < len(data) and data[idx] == '':
                idx += 1
            if idx >= len(data):
                break
            a.append(data[idx])
            idx += 1

        # Read matrix b
        b = []
        for _ in range(n):
            while idx < len(data) and data[idx] == '':
                idx += 1
            if idx >= len(data):
                break
            b.append(data[idx])
            idx += 1

        # Compute difference matrix d
        d = []
        for i in range(n):
            row = []
            for j in range(n):
                row.append(str(int(a[i][j]) ^ int(b[i][j])))
            d.append(''.join(row))

        # Check if all rows are identical
        if all(row == d[0] for row in d):
            results.append("YES")
        else:
            results.append("NO")

