import sys

def solve():
    # Read input
    weights_available = sys.stdin.readline().strip()
    m = int(sys.stdin.readline().strip())

    # Parse available weights
    available_weights = []
    for i in range(10):
        if weights_available[i] == '1':
            available_weights.append(i + 1)

    # Dynamic programming approach
    # dp[position][left_sum][right_sum][last_weight] = path
    # We'll use a dictionary to store states
    from collections import defaultdict

    # Initialize
    dp = {}
    initial_state = (0, 0, 0, None)
    dp[initial_state] = []

    # Try to find a valid sequence
    for position in range(m):
        new_dp = {}
        for state, path in dp.items():
            pos, left, right, last = state

            # Try all available weights
            for weight in available_weights:
                if last is not None and last == weight:
                    continue  # Skip if same as last weight

                # Calculate new sums
                if pos % 2 == 0:
                    # Left scalepan
                    new_left = left + weight
                    new_right = right
                else:
                    # Right scalepan
                    new_left = left
                    new_right = right + weight

                # Check if current scalepan outweighs the other
                if pos % 2 == 0:
                    # Left should outweigh right
                    if new_left <= new_right:
                        continue
                else:
                    # Right should outweigh left
                    if new_right <= new_left:
                        continue

                new_pos = pos + 1
                new_state = (new_pos, new_left, new_right, weight)
                new_path = path + [weight]

                new_dp[new_state] = new_path

        dp = new_dp

        if not dp:
            break  # No valid sequences

    if dp:
        # Find any valid sequence
        for state, path in dp.items():
            print("YES")
            print(' '.join(map(str, path)))
            return
    else:
        print("NO")

if __name__ == "__main__":
    solve()
