def solve(n):
    """Find the minimum number of lea operations to multiply by n."""

    # Base case: n = 1, no operations needed (result is already in eax)
    if n == 1:
        return 0, []

    # We need to find the minimum number of operations to build up n
    # We can use 1, 2, 4, and 8 as building blocks

    # Try to find a decomposition of n as 1 + 2*a or 1 + 4*a or 1 + 8*a
    if n % 2 == 0:
        remainder = n // 2
        return 1, [f"lea ebx, [{2}*eax]"]  # Direct scaling

    # If not divisible by 2, try combinations
    # Find the largest k such that n % k == 0
    for k in [8, 4, 2]:
        if n % k == 0:
            remainder = n // k
            if remainder == 1:
                return 1, [f"lea ebx, [{k}*eax]"]
            # Need to build remainder
            return 2, [f"lea ecx, [eax + {k}*eax]", f"lea ebx, [{remainder}*ecx]"]

    # If we get here, we need at least 3 operations
    return 3, [f"lea ebx, [eax + 1*eax]", f"lea ecx, [ebx + 4*ebx]", f"lea edx, [eax + 8*ecx]"]

def main():
    n = int(input().strip())
    p, commands = solve(n)
    print(p)
    for cmd in commands:
        print(cmd)

if __name__ == "__main__":
    main()
