def calculate_grundy(n):
    """Calculate the Grundy number for a pile of size n using memoization."""
    memo = {}

def g(n):
        if n <= 0:
            return 0
        if n in memo:
            return memo[n]

        # Find all possible splits
        moves = []
        for k in range(2, n + 1):
            # Check if we can split n into k piles
            if (n + k * (k - 1) // 2) % k == 0:
                a = (n + k * (k - 1) // 2) // k
                piles = [a - i for i in range(k)]

                # Calculate XOR of Grundy numbers for the resulting piles
                xor_sum = 0
                for pile in piles:
                    xor_sum ^= g(pile)

                moves.append(xor_sum)

        # Grundy number is the mex (minimum excludant) of all possible moves
        mex = 0
        while mex in moves:
            mex += 1

        memo[n] = mex
        return mex

