import sys

def count_k_interesting_pairs(n, k, a):
    """Count the number of k-interesting pairs in the array."""

    # Count occurrences of each number
    count = {}
    for num in a:
        count[num] = count.get(num, 0) + 1

    # If k == 0, count pairs of equal numbers
    if k == 0:
        # For each number, count pairs of equal numbers
        # C(n, 2) = n * (n - 1) / 2 for each occurrence
        total = 0
        for num in count:
            cnt = count[num]
            total += cnt * (cnt - 1) // 2
        return total

    # For k > 0, count pairs where XOR has exactly k bits set
    total = 0

    # For each pair of numbers, count if their XOR has exactly k bits set
    for i in range(n):
        for j in range(i + 1, n):
            if bin(a[i] ^ a[j]).count('1') == k:
                total += 1

    return total

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:2 + n]))

    result = count_k_interesting_pairs(n, k, a)
    print(result)

if __name__ == "__main__":
    main()
