import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    total_sum = sum(a)

    nice_indices = []

    for j in range(n):
        # Check if there exists an element a[i] such that a[j] = total_sum - 2 * a[i]
        # This means 2 * a[i] = total_sum - a[j]
        # So a[i] = (total_sum - a[j]) / 2

        target = (total_sum - a[j]) / 2

        # Check if target is an integer and exists in the array (excluding a[j] itself)
        if target.is_integer():
            target_int = int(target)

            # Check if target_int exists in the array
            if target_int in a:
                # Check if there's at least one occurrence of target_int that is not a[j]
                # If a[j] == target_int, we need at least two occurrences
                if target_int != a[j] or a.count(target_int) > 1:
                    nice_indices.append(j + 1)  # 1-indexed

    print(len(nice_indices))
    if nice_indices:
        print(' '.join(map(str, nice_indices)))

if __name__ == "__main__":
    solve()
