    # Count occurrences of each value
    value_counts = {}
    for val in a:
        value_counts[val] = value_counts.get(val, 0) + 1

    nice_indices = []

    for idx in range(n):
        val = a[idx]
        # After removing val, the sum is total_sum - val
        remaining_sum = total_sum - val

        # Check if remaining_sum is even
        if remaining_sum % 2 != 0:
            continue

        target = remaining_sum // 2

        # Check if target exists in the array
        if target in value_counts:
            count = value_counts[target]

            # If target == val, we need at least 2 occurrences
            if target == val:
                if count >= 2:
                    nice_indices.append(idx + 1)  # 1-indexed
            else:
                # If target != val, we need at least 1 occurrence
                if count >= 1:
                    nice_indices.append(idx + 1)

    # Output results
    print(len(nice_indices))
    if nice_indices:
        print(' '.join(map(str, nice_indices)))

if __name__ == "__main__":
