import sys

def solve() -> None:
    line = sys.stdin.readline().strip()
    if not line:
        return

    b, n, c = map(int, line.split())

    # Calculate total numbers of length n in base b
    # First digit: (b-1) choices (1 to b-1)
    # Remaining n-1 digits: b choices each (0 to b-1)
    total = (b - 1) * (b ** (n - 1))

    # Calculate numbers on last page
    if total % c == 0:
        last_page = c
    else:
        last_page = total % c

    print(last_page)

if __name__ == "__main__":
    solve()
